import type { CodeFile } from './types'

interface TabProps {
  files: CodeFile[]
  addFile: (name: string) => void
  changeFile: (name: string) => void
  closeFile: (name: string) => void
}

export function Tabs(props: TabProps) {
  function newTab() {
    const newFileName = getNewName(props.files)
    if (newFileName) {
      props.addFile(newFileName)
    }
  }

  function closeTab(event: MouseEvent, name: string) {
    event.stopPropagation()
    props.closeFile(name)
  }

  return (
    <div class="tabs">
      {tabs(props.files).map(({ name, active }) => (
        <div class={active ? 'tab active' : 'tab'} onClick={() => props.changeFile(name)}>
          {name}
          <span class="close" onClick={(e) => closeTab(e, name)}>
            ✕
          </span>
        </div>
      ))}
      <div class="tab new" onClick={newTab}>
        +
      </div>
    </div>
  )
}

interface Tab {
  name: string
  active: boolean
}

function tabs(files: CodeFile[]): Tab[] {
  const active = findActive(files)
  return files.map(({ name, activeIndex }) => ({ name, active: activeIndex === active }))
}

function getNewName(files: CodeFile[]): string | null {
  let defaultName: string = 'new.py'
  let num = 1
  while (files.find((f) => f.name === defaultName)) {
    defaultName = `new_${num}.py`
    num++
  }

  let name = prompt('File name?', defaultName)
  while (name !== null && files.find((f) => f.name === name)) {
    name = prompt(`File name ${name} already exists. Try another name?`, defaultName)
  }
  return name
}

export const findActive = (files: CodeFile[]): number =>
  files.reduce((acc, { activeIndex }) => Math.max(acc, activeIndex), 0)

import * as monaco from 'monaco-editor'

import type { CodeFile } from './types'

export const { KeyMod, KeyCode } = monaco

monaco.editor.defineTheme('custom-dark', {
  base: 'vs-dark',
  inherit: true,
  rules: [],
  colors: {
    'editor.background': '#1e1f2e',
  },
})

export class Editor {
  private readonly editor: monaco.editor.IStandaloneCodeEditor
  private readonly languages: monaco.languages.ILanguageExtensionPoint[]

  constructor(element: HTMLElement, file: CodeFile | undefined) {
    this.languages = monaco.languages.getLanguages()
    this.editor = monaco.editor.create(element, {
      value: file ? file.content : '',
      language: this.getLanguage(file),
      theme: 'custom-dark',
      automaticLayout: true,
      minimap: {
        enabled: false,
      },
    })
  }

  getValue(): string {
    return this.editor.getValue()
  }

  addCommand(keybinding: monaco.KeyCode, handler: () => void) {
    this.editor.addCommand(keybinding, handler)
  }

  onDidChangeModelContent(handler: () => void) {
    this.editor.onDidChangeModelContent(handler)
  }

  focus() {
    this.editor.focus()
  }

  setFile(file: CodeFile) {
    const language = this.getLanguage(file)
    if (language) {
      monaco.editor.setModelLanguage(this.editor.getModel()!, language)
    }
    this.editor.setValue(file.content)
  }

  private getLanguage(file: CodeFile | undefined): string {
    if (!file) {
      return 'txt'
    }
    const nameParts = file.name.split('.')
    if (nameParts.length >= 2) {
      const fileExtension = '.' + nameParts[nameParts.length - 1]
      if (fileExtension === '.toml') {
        // monaco doesn't yet support toml, use ruby as a workaround 🤮
        // https://github.com/microsoft/monaco-editor/issues/2798#issuecomment-2390998775
        return 'ruby'
      }
      for (const { extensions, id } of this.languages) {
        if (extensions && extensions.includes(fileExtension)) {
          return id
        }
      }
    }
    if (file.content.length > 0) {
      const contentFirstLine = file.content.split('\n')[0]
      for (const { firstLine, id } of this.languages) {
        if (firstLine) {
          const firstLineRegex = new RegExp(firstLine)
          if (firstLineRegex.test(contentFirstLine)) {
            return id
          }
        }
      }
    }
    return 'txt'
  }
}

import { z } from 'zod'

import { filesPath, toHexString, MAX_FILE_SIZE } from './api'

export async function createNew(url: URL, request: Request, env: Env): Promise<Response> {
  if (request.method !== 'GET') {
    return new Response('Method not allowed', { status: 405 })
  }
  const filesParam = url.searchParams.get('files')
  if (!filesParam) {
    return new Response('No "files" found in in URL parameters', { status: 400 })
  }
  const hash = await hashString(filesParam)
  const readKey = hash.substring(0, 16)
  const existing = await env.BUCKET.head(filesPath(readKey))
  if (!existing) {
    const result = parseFiles(filesParam)
    if (result instanceof Response) {
      return result
    }
    await env.BUCKET.put(filesPath(readKey), JSON.stringify({ files: result }))
  }
  let redirectUrl = `${url.origin}/store/${readKey}`
  const tab = url.searchParams.get('tab')
  if (tab) {
    redirectUrl += `?tab=${tab}`
  }
  return Response.redirect(redirectUrl, 302)
}

const filesSchema = z.array(
  z.object({
    name: z.string(),
    content: z.string(),
    activeIndex: z.number().default(0),
  }),
)

interface File {
  name: string
  content: string
  // highest activeIndex value is the active tab
  activeIndex: number
}

function parseFiles(filesParam: string): Response | File[] {
  if (filesParam.length > MAX_FILE_SIZE) {
    return new Response('Invalid body, 10kB limit exceeded', { status: 413 })
  }
  let rawFiles
  try {
    rawFiles = JSON.parse(filesParam)
  } catch (e) {
    return new Response(`Invalid JSON in "files": ${e}`, { status: 400 })
  }
  let files: File[]
  try {
    files = filesSchema.parse(rawFiles)
  } catch (e) {
    return new Response(`Invalid "files": ${e}`, { status: 400 })
  }
  if (files.length === 0) {
    return new Response('No files found', { status: 400 })
  }
  if (files.every((f) => f.activeIndex === 0)) {
    files[0].activeIndex = 1
  }
  return files
}

const encoder = new TextEncoder()

async function hashString(message: string): Promise<string> {
  const data = encoder.encode(message)
  const hashBuffer = await crypto.subtle.digest('SHA-256', data)
  return toHexString(new Uint8Array(hashBuffer))
}

import { createSignal, onMount } from 'solid-js'

import Convert from 'ansi-to-html'
import Editor from './editor'
import Worker from './worker?worker'
import type { WorkerResponse, RunCode, CodeFile, Versions } from './types'

const decoder = new TextDecoder()
const ansiConverter = new Convert({ colors: { 1: '#CE9178', 4: '#569CFF', 5: '#F00' } })

export default function () {
  const [status, setStatus] = createSignal<string | null>(null)
  const [running, setRunning] = createSignal(false)
  const [installed, setInstalled] = createSignal('')
  const [outputHtml, setOutputHtml] = createSignal('')
  const [versions, setVersions] = createSignal<Versions | null>(null)
  let terminalOutput = ''
  let worker: Worker
  let outputRef!: HTMLPreElement

  onMount(async () => {
    worker = new Worker()
    worker.onmessage = ({ data }: { data: WorkerResponse }) => {
      let newTerminalOutput = false
      if (data.kind == 'print') {
        newTerminalOutput = true
        for (const chunk of data.data) {
          terminalOutput += decoder.decode(chunk)
        }
      } else if (data.kind == 'status') {
        setStatus(data.message)
      } else if (data.kind == 'error') {
        newTerminalOutput = true
        terminalOutput += data.message
      } else if (data.kind == 'installed') {
        setInstalled(data.message.length > 0 ? `Installed dependencies: ${data.message}` : '')
      } else if (data.kind == 'end') {
        setRunning(false)
      } else {
        setVersions(data as Versions)
      }

      if (newTerminalOutput) {
        // escape HTML codes in the terminal output
        const escapedOutput = escapeHTML(terminalOutput)
        // replace ansi links with html links since ansi-to-html doesn't support this properly
        let terminalHtml = replaceAnsiLinks(escapedOutput)
        // convert other ansi codes to html
        terminalHtml = ansiConverter.toHtml(terminalHtml)
        // set the output
        setOutputHtml(terminalHtml)
        // scrolls to the bottom of the div
        outputRef.scrollTop = outputRef.scrollHeight
      }
    }
  })

  async function runCode(files: CodeFile[]) {
    setRunning(true)
    setStatus('Starting Python...')
    setInstalled('')
    setOutputHtml('')
    terminalOutput = ''
    worker!.postMessage({ files } as RunCode)
  }

  // noinspection JSUnusedAssignment
  return (
    <main>
      <header>
        <h1>pydantic.run</h1>
        <aside>
          Python browser sandbox, see{' '}
          <a href="https://github.com/pydantic/pydantic.run" target="_blank">
            github.com/pydantic/pydantic.run
          </a>{' '}
          for more info. <a href="/blank">reset sandbox</a>.
        </aside>
      </header>
      <section>
        <Editor runCode={runCode} running={running()} />
        <div class="col">
          <div class="status my-5">{status() || <>&nbsp;</>}</div>
          <div class="installed">{installed()}</div>
          <pre class="output" innerHTML={outputHtml()} ref={outputRef}></pre>
          <Versions versions={versions()} />
        </div>
      </section>
    </main>
  )
}

const escapeEl = document.createElement('textarea')
function escapeHTML(html: string): string {
  escapeEl.textContent = html
  return escapeEl.innerHTML
}

// hellish regex to replace ansi links with html links since ansi-to-html doesn't know how
// warning this may be very bittle! it's written to work for the logfire project URL currently printed
// by the logfire SDK
function replaceAnsiLinks(terminalOutput: string): string {
  return terminalOutput.replace(
    // eslint-disable-next-line no-control-regex
    /\x1B]8;id=\d+;(.+?)\x1B\\(?:\x1B\[\d+;\d+m)?(.+?)(?:\x1B\[0m)?\x1B]8;;\x1B\\/g,
    (_, url, text) => `<a href="${url}" target="_blank">${text}</a>`,
  )
}

function Versions(props: { versions: Versions | null }) {
  return (
    <div class="status text-right smaller">
      {props.versions && (
        <>
          <a
            href={`https://www.python.org/downloads/release/python-${props.versions.python.replace(/\./g, '')}/`}
            target="_blank"
          >
            Python {props.versions.python}
          </a>
          ,{' '}
          <a
            href={`https://pyodide.org/en/stable/project/changelog.html#version-${props.versions.pyodide.replace(/\./g, '-')}`}
            target="_blank"
          >
            Pyodide {props.versions.pyodide}
          </a>
        </>
      )}
    </div>
  )
}

